def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/environment/input/pleasure_bay_and_castle_island_beach_datasheet.csv'
    # File has a multi-row header/section labels. Read without header to locate/construct the real header.
    return pd.read_csv(path, header=None, dtype=str)

def process(pleasureBayData) -> pd.DataFrame:
    import pandas as pd
    import numpy as np

    df = pleasureBayData.copy()

    # Find the first row that looks like the column header row (starts with 'Sample Date')
    header_idx = None
    for i in range(min(len(df), 80)):
        v = str(df.iloc[i, 0])
        if v.strip().lower() in {'sample date', 'date', 'sample_date'}:
            header_idx = i
            break
    if header_idx is None:
        for i in range(min(len(df), 120)):
            v = str(df.iloc[i, 0]).lower()
            if 'sample' in v and 'date' in v:
                header_idx = i
                break

    if header_idx is None:
        for i in range(min(len(df), 200)):
            v = str(df.iloc[i, 0])
            if any(m in v for m in ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']):
                header_idx = i - 1
                break

    header = df.iloc[header_idx].tolist() if header_idx is not None else df.iloc[2].tolist()
    data = df.iloc[(header_idx + 1) if header_idx is not None else 3:].copy()

    # Ensure unique column labels (duplicate labels can cause boolean indexing errors)
    def make_unique(cols):
        seen = {}
        out = []
        for c in cols:
            c = str(c).strip() if pd.notna(c) else ''
            base = c if c != '' else 'col'
            if base not in seen:
                seen[base] = 0
                out.append(base)
            else:
                seen[base] += 1
                out.append(f"{base}.{seen[base]}")
        return out

    data.columns = make_unique(header)

    # Drop fully empty rows
    data = data.dropna(how='all')

    def find_col(keywords):
        for c in data.columns:
            cl = str(c).lower()
            if all(k in cl for k in keywords):
                return c
        return None

    date_col = find_col(['date'])
    rain_col = find_col(['rain'])
    entero_col = find_col(['enteroc'])
    site_col = find_col(['site']) or find_col(['station']) or find_col(['location'])

    keep_cols = [c for c in [date_col, site_col, rain_col, entero_col] if c is not None]
    out = data[keep_cols].copy()

    if date_col is not None:
        out[date_col] = pd.to_datetime(out[date_col], errors='coerce')

    def to_num(x):
        if pd.isna(x):
            return np.nan
        s = str(x).strip()
        s = s.replace('<', '').replace('>', '')
        s2 = ''.join(ch for ch in s if ch.isdigit() or ch in ['.', '-'])
        if s2 in ['', '.', '-']:
            return np.nan
        try:
            return float(s2)
        except Exception:
            return np.nan

    if rain_col is not None:
        out[rain_col] = out[rain_col].map(to_num)
    if entero_col is not None:
        out[entero_col] = out[entero_col].map(to_num)

    if site_col is not None:
        mask_pb = out[site_col].astype(str).str.contains('Pleasure Bay', case=False, na=False)
        out = out.loc[mask_pb]

    if entero_col is not None:
        # Avoid issues if entero_col selection yields multiple columns (shouldn't after make_unique, but safe)
        series = out[entero_col]
        if isinstance(series, pd.DataFrame):
            series = series.iloc[:, 0]
        out = out.loc[series > 104]

    rename = {}
    if date_col is not None:
        rename[date_col] = 'sampleDate'
    if site_col is not None:
        rename[site_col] = 'site'
    if rain_col is not None:
        rename[rain_col] = 'rain1DayPrior'
    if entero_col is not None:
        rename[entero_col] = 'enterococcus'
    out = out.rename(columns=rename)

    return out.reset_index(drop=True)

def process(pleasureBayClean) -> pd.DataFrame:
    import pandas as pd

    df = pleasureBayClean.copy()
    if 'rain1DayPrior' not in df.columns:
        return pd.DataFrame([{'avgRain1DayPrior': None, 'nFailedSamples': len(df)}])

    avg = df['rain1DayPrior'].mean()
    return pd.DataFrame([{
        'avgRain1DayPrior': round(float(avg), 2) if pd.notna(avg) else None,
        'nFailedSamples': int(df['rain1DayPrior'].notna().sum()),
        'nFailedTotalRows': int(len(df))
    }])
